function choose_mean_test(direction, n, $sigma_known$, mu0):
    H0 <- "mu = " + mu0

    if direction == "higher":
        Ha <- "mu > " + mu0
    else if direction == "lower":
        Ha <- "mu < " + mu0
    else:
        Ha <- "mu != " + mu0

    if $sigma_known$ == true:
        statistic <- "z"
    else if n >= 30:
        statistic <- "z using s as an approximation"
    else:
        statistic <- "t with n - 1 degrees of freedom"

    return H0, Ha, statistic
```

